"use strict";(self.webpackChunk_ai_autistic_intelligence_docusaurus_theme=self.webpackChunk_ai_autistic_intelligence_docusaurus_theme||[]).push([["1877"],{3982(e){e.exports=JSON.parse('{"version":{"pluginId":"ferrox-front","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"ferroxFrontSidebar":[{"type":"category","label":"\u26A1 Ferrox Front Wasm 2.0","collapsed":false,"items":[{"type":"link","href":"/docs/ferrox-front/overview","label":"Visione Zero-JS & Architettura","docId":"overview","unlisted":false},{"type":"link","href":"/docs/ferrox-front/trading-desk","label":"Live Trading Desk (Interactive Wasm)","docId":"trading-desk","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components","label":"Catalogo Componenti Enterprise","docId":"components","unlisted":false},{"type":"link","href":"/docs/ferrox-front/datagrid","label":"Enterprise DataGrid (1M Rows & CSV Export)","docId":"datagrid","unlisted":false},{"type":"link","href":"/docs/ferrox-front/charts","label":"Motore Finanziario Vettoriale SVG","docId":"charts","unlisted":false}],"collapsible":true}]},"docs":{"architectures/architecture":{"id":"architectures/architecture","title":"Core WebAssembly System Architecture","description":"The ferrox-front architecture is designed around zero-cost abstractions, fine-grained reactive dependency graphs, single-threaded browser thread execution, WebAssembly linear memory layout, and WebGL rendering acceleration."},"charts":{"id":"charts","title":"Motore Finanziario Vettoriale SVG","description":"ferrox-front-charts \xe8 una libreria vettoriale SVG ad altissima precisione progettata specificamente per cruscotti finanziari, trading desk e visualizzazioni quantitative, con zero dipendenze JavaScript o Canvas.","sidebar":"ferroxFrontSidebar"},"components":{"id":"components","title":"Catalogo Componenti Enterprise","description":"La crate ferrox-front-ui implementa un Design System moderno, fortemente tipizzato e conforme agli standard WCAG 2.1 AA. Tutti i componenti supportano varianti visive avanzate, micro-animazioni, stati accessibili :focus-visible e glassmorphism.","sidebar":"ferroxFrontSidebar"},"datagrid":{"id":"datagrid","title":"Enterprise DataGrid (1M Rows & CSV Export)","description":"Il componente EnterpriseDataGrid di Ferrox Front \xe8 progettato per colmare e superare le capacit\xe0 di librerie complesse come AG-Grid Enterprise e TanStack Table, garantendo zero garbage collection pauses anche su volumi di 1.000.000 di record.","sidebar":"ferroxFrontSidebar"},"fundamentals/core":{"id":"fundamentals/core","title":"Core Kernel, Context Providers & Resource Managers","description":"The ferrox-front-core crate is the foundation kernel of the Ferrox WebAssembly frontend framework. It manages component context providers (providecontext, usecontext), async resource loaders (create_resource), effect batch schedulers, and browser lifecycle event hooks."},"fundamentals/macros":{"id":"fundamentals/macros","title":"Procedural Macros, Component Annotations & Code Generation","description":"The ferrox-front-macro crate provides Rust procedural macros (#[component], view!, derive(Store)) that transform declarative UI components and reactive state structs into optimized WebAssembly execution code."},"fundamentals/reactivity":{"id":"fundamentals/reactivity","title":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","description":"The ferrox-front-core reactivity engine provides fine-grained reactive state management in WebAssembly. Built on push-pull signal graphs, it exposes Signal, ReadSignal, WriteSignal, Memo, and Effect primitives without relying on Virtual DOM diffing."},"fundamentals/routing":{"id":"fundamentals/routing","title":"Client-Side Router, Route Guards & Lazy Loading","description":"The ferrox-front-router crate delivers client-side SPA navigation for WebAssembly apps. It features HTML5 History API integration, route path parameter matching, nested layout outlets, route protection guards, and code-split WebAssembly module lazy loading."},"fundamentals/templates":{"id":"fundamentals/templates","title":"Virtual DOM Templates, JSX Engine & HTML Macros","description":"The ferrox-front-templates crate delivers zero-allocation HTML templating, WebAssembly compile-time JSX expansion, reactive DOM element patching, and SSR (Server-Side Rendering) string interpolation for Rust web applications."},"overview":{"id":"overview","title":"Visione Zero-JS & Architettura","description":"Ferrox Front \xe8 un framework frontend e Design System enterprise all\'avanguardia scritto interamente in Rust WebAssembly (wasm32-unknown-unknown), progettato specificamente per eliminare JavaScript, React e i bundler npm dalle applicazioni web mission-critical e dai sistemi finanziari ad alta frequenza.","sidebar":"ferroxFrontSidebar"},"overview/intro":{"id":"overview/intro","title":"Introduction & Ferrox-Front Architecture","description":"Welcome to Ferrox-Front, the high-performance WebAssembly (Wasm) frontend framework written in pure Rust. It combines fine-grained reactive signals, compile-time JSX HTML templates, zero-trust cryptographic security, real-time WebSocket state synchronization, and GPU-accelerated WebGL charts into a unified application suite."},"overview/quickstart":{"id":"overview/quickstart","title":"Quickstart Guide","description":"This guide demonstrates how to install prerequisites, build your first WebAssembly application in Rust using Ferrox Front, and run it in the browser."},"security/security":{"id":"security/security","title":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","description":"The ferrox-front-security crate delivers zero-trust security for Rust WebAssembly applications. It features browser WebCrypto API bindings (AES-256-GCM, RSA-OAEP, ECDSA), zero-copy linear memory wiping (Zeroize), secure storage adapters, and HTML XSS sanitizers."},"trading-desk":{"id":"trading-desk","title":"Live Trading Desk (Interactive Wasm)","description":"Questa pagina ospita l\'applicazione di riferimento enterprise Ferrox Live Trading Desk, compilata per target wasm32-unknown-unknown ed eseguita nativamente all\'interno del tuo browser.","sidebar":"ferroxFrontSidebar"},"transports/ws":{"id":"transports/ws","title":"Real-Time WebSockets Engine (ferrox-front-ws)","description":"ferrox-front-ws provides an asynchronous WebAssembly WebSocket client engine built natively for Rust frontends. It bridges browser WebSocket APIs (web_sys::WebSocket) with Ferrox Front\'s reactive Signals graph (Signal), enabling low-latency, real-time bi-directional streaming for dashboards, chat applications, financial tickers, and live notification systems."},"ui/components":{"id":"ui/components","title":"Component Library & Interactive Playground","description":"Explore and interact with the Ferrox Front component library live in your browser using our Nivo-Style Interactive Playground."},"ui/ui-components":{"id":"ui/ui-components","title":"Glassmorphism Design System (ferrox-front-ui)","description":"ferrox-front-ui provides a complete, enterprise-grade Glassmorphism Design System for WebAssembly applications. It includes Design Tokens, a 12-column responsive layout grid, a Virtualized DataGrid (1,000,000+ rows), and a comprehensive library of pre-styled UI components."}}}}')}}]);